ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
payload map ((item, index) -> {
  BirthDate: item.BirthDate as Date {format: "yyyyMMdd"} as String {format: "yyyy-MM-dd"}
})

%dw 2.0
output application/json
---
payload map ((item, index) -> {
  examDate: item.TestDate as Date {format: "yyyyMMdd"} as String {format: "yyyy-MM-dd"}
})

%dw 2.0
output application/json
---
[{
	"Id": payload.Id,
	"VerificationStatus": if(vars.initialPayload[0].PassFail_GeneralPortion == 'P') "Pass" else if(vars.initialPayload[0].PassFail_GeneralPortion == 'F') "Fail" else "No Show",
	//"ExaminationDate": vars.ExamDate[0].examDate as Date {format: "yyyy-MM-dd"} at "UTC") as DateTime {format: "yyyy-MM-dd'T'00:00:00.000'Z'"},
	"Notes_Comments__c": now() as Date as String ++ ' ' ++ '-' ++ ' ' ++ "Exam Result added by AutoUpdate process",
	"Credential__c": vars.credential

}]
